s.\n- Remove outdated LICENSE and CHANGELOG files.","tree":{"sha":"71877f59885d57cc5d7a1ce544d29007ba7632da","url":"https://api.github.com/repos/Guneshbari/mock-mentor/git/trees/71877f59885d57cc5d7a1ce544d29007ba7632da"},"url":"https://api.github.com/repos/Guneshbari/mock-mentor/git/commits/fa6a617b37825f5d8233895de8cf39a03142726d","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/148274218?v=4","events_url":"https://api.github.com/users/Guneshbari/events{/privacy}","followers_url":"https://api.github.com/users/Guneshbari/followers","following_url":"https://api.github.com/users/Guneshbari/following{/other_user}","gists_url":"https://api.github.com/users/Guneshbari/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/Guneshbari","id":148274218,"login":"Guneshbari","node_id":"U_kgDOCNZ8Kg","organizations_url":"https://api.github.com/users/Guneshbari/orgs","received_events_url":"https://api.github.com/users/Guneshbari/received_events","repos_url":"https://api.github.com/users/Guneshbari/repos","site_admin":false,"starred_url":"https://api.github.com/users/Guneshbari/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/Guneshbari/subscriptions","type":"User","url":"https://api.github.com/users/Guneshbari","user_view_type":"public"},"html_url":"https://github.com/Guneshbari/mock-mentor/commit/fa6a617b37825f5d8233895de8cf39a03142726d","node_id":"C_kwDORAv4yNoAKGZhNmE2MTdiMzc4MjVmNWQ4MjMzODk1ZGU4Y2YzOWEwMzE0MjcyNmQ","parents":[{"html_url":"https://github.com/Guneshbari/mock-mentor/commit/196682b99420f0e6af74fb07824af8708837958a","sha":"196682b99420f0e6af74fb07824af8708837958a","url":"https://api.github.com/repos/Guneshbari/mock-mentor/commits/196682b99420f0e6af74fb07824af8708837958a"}],"sha":"fa6a617b37825f5d8233895de8cf39a03142726d","url":"https://api.github.com/repos/Guneshbari/mock-mentor/commits/fa6a617b37825f5d8233